use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::time::{SystemTime, Duration, UNIX_EPOCH};
use ring::aead::{self, Aad, LessSafeKey, Nonce, UnboundKey, CHACHA20_POLY1305};
use ring::rand::{SystemRandom, SecureRandom};

const MAX_REQUESTS_PER_WINDOW: u32 = 100;
const WINDOW_DURATION_SECS: u64 = 60;
const MAX_RETRIES: u32 = 3;

#[derive(Clone)]
struct RateLimitEntry {
    count: u32,
    window_start: u64,
}

struct CryptoContext {
    key: LessSafeKey,
    rng: SystemRandom,
    nonce_counter: u64,
}

impl CryptoContext {
    fn new() -> Self {
        let rng = SystemRandom::new();
        let mut key_bytes = [0u8; 32];
        rng.fill(&mut key_bytes).unwrap();
        let unbound = UnboundKey::new(&CHACHA20_POLY1305, &key_bytes).unwrap();
        CryptoContext {
            key: LessSafeKey::new(unbound),
            rng,
            nonce_counter: 0,
        }
    }

    fn generate_nonce(&mut self) -> [u8; 12] {
        // Use atomic counter to guarantee unique nonces
        // Each encryption gets a strictly unique nonce value
        self.nonce_counter += 1;
        let mut nonce_bytes = [0u8; 12];
        let counter_bytes = self.nonce_counter.to_le_bytes();
        nonce_bytes[..8].copy_from_slice(&counter_bytes);
        // Fill remaining bytes with randomness for extra safety
        let mut rand_part = [0u8; 4];
        self.rng.fill(&mut rand_part).unwrap();
        nonce_bytes[8..12].copy_from_slice(&rand_part);
        nonce_bytes
    }

    fn current_window(&self) -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs() / WINDOW_DURATION_SECS
    }

    fn encrypt_response(&mut self, _client_id: &str, plaintext: &[u8]) -> Vec<u8> {
        let nonce_bytes = self.generate_nonce();
        let nonce = Nonce::assume_unique_for_key(nonce_bytes);
        let mut in_out = plaintext.to_vec();
        self.key.seal_in_place_append_tag(nonce, Aad::empty(), &mut in_out).unwrap();
        let mut result = nonce_bytes.to_vec();
        result.extend_from_slice(&in_out);
        result
    }
}

struct MobileBackend {
    rate_limits: Arc<Mutex<HashMap<String, RateLimitEntry>>>,
    crypto: Arc<Mutex<CryptoContext>>,
    pending_retries: Arc<Mutex<HashMap<String, u32>>>,
}

impl MobileBackend {
    fn new() -> Self {
        MobileBackend {
            rate_limits: Arc::new(Mutex::new(HashMap::new())),
            crypto: Arc::new(Mutex::new(CryptoContext::new())),
            pending_retries: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn check_rate_limit(&self, client_id: &str) -> bool {
        let mut limits = self.rate_limits.lock().unwrap();
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        let entry = limits.entry(client_id.to_string()).or_insert(RateLimitEntry {
            count: 0,
            window_start: now,
        });
        if now - entry.window_start >= WINDOW_DURATION_SECS {
            entry.count = 0;
            entry.window_start = now;
        }
        if entry.count >= MAX_REQUESTS_PER_WINDOW {
            return false;
        }
        entry.count += 1;
        true
    }

    fn handle_request(&self, client_id: &str, payload: &[u8]) -> Result<Vec<u8>, String> {
        if !self.check_rate_limit(client_id) {
            return Err("rate_limited".to_string());
        }
        let response_data = self.process_payload(payload)?;
        let mut crypto = self.crypto.lock().unwrap();
        Ok(crypto.encrypt_response(client_id, &response_data))
    }

    fn handle_with_retry(&self, client_id: &str, payload: &[u8]) -> Result<Vec<u8>, String> {
        let mut retries = self.pending_retries.lock().unwrap();
        let attempt = retries.entry(client_id.to_string()).or_insert(0);

        for _ in 0..MAX_RETRIES {
            match self.handle_request(client_id, payload) {
                Ok(response) => {
                    *attempt = 0;
                    return Ok(response);
                }
                Err(e) if e == "rate_limited" => {
                    *attempt += 1;
                    std::thread::sleep(Duration::from_millis(100 * (*attempt as u64)));
                }
                Err(e) => return Err(e),
            }
        }
        Err("max_retries_exceeded".to_string())
    }

    fn process_payload(&self, payload: &[u8]) -> Result<Vec<u8>, String> {
        if payload.is_empty() {
            return Err("empty_payload".to_string());
        }
        // Simulate processing - echo back with metadata
        let mut result = Vec::new();
        result.extend_from_slice(b"OK:");
        result.extend_from_slice(payload);
        Ok(result)
    }
}

fn main() {
    let backend = MobileBackend::new();
    let client = "mobile-device-abc123";
    let payload = b"fetch_user_profile";

    match backend.handle_with_retry(client, payload) {
        Ok(encrypted) => println!("Response: {} bytes", encrypted.len()),
        Err(e) => eprintln!("Error: {}", e),
    }
}
